<?php require 'config.php';login_required();$admin=$_SESSION['role']==='admin';check_csrf();if($admin&&$_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';if($a==='save'){$id=(int)($_POST['id']??0);$v=[trim($_POST['title']??''),trim($_POST['author']??''),trim($_POST['isbn']??''),trim($_POST['category']??''),max(0,(int)($_POST['quantity']??0)),trim($_POST['description']??'')];if($v[0]&&$v[1]){if($id){$s=$pdo->prepare('UPDATE books SET title=?,author=?,isbn=?,category=?,available=GREATEST(0,available+(?-quantity)),quantity=?,description=? WHERE id=?');$s->execute([$v[0],$v[1],$v[2],$v[3],$v[4],$v[4],$v[5],$id]);}else{$s=$pdo->prepare('INSERT INTO books(title,author,isbn,category,quantity,available,description) VALUES(?,?,?,?,?,?,?)');$s->execute([$v[0],$v[1],$v[2],$v[3],$v[4],$v[4],$v[5]]);}notice('Book saved.');}header('Location: books.php');exit;}if($a==='issue'){$book=(int)$_POST['book'];$member=(int)$_POST['member'];$due=$_POST['due']??'';$s=$pdo->prepare('SELECT available FROM books WHERE id=?');$s->execute([$book]);if((int)$s->fetchColumn()>0&&strtotime($due)>=strtotime(date('Y-m-d'))){$pdo->beginTransaction();$pdo->prepare('UPDATE books SET available=available-1 WHERE id=?')->execute([$book]);$pdo->prepare("INSERT INTO loans(book_id,user_id,issued_by,due_date,status) VALUES(?,?,?,?,'issued')")->execute([$book,$member,$_SESSION['uid'],$due]);$pdo->commit();notice('Loan recorded.');}else notice('No copies available or due date invalid.');header('Location: books.php');exit;}if($a==='return'){$id=(int)$_POST['loan'];$s=$pdo->prepare("SELECT book_id FROM loans WHERE id=? AND status='issued'");$s->execute([$id]);if($b=$s->fetchColumn()){$pdo->beginTransaction();$pdo->prepare("UPDATE loans SET status='returned',returned_at=NOW() WHERE id=?")->execute([$id]);$pdo->prepare('UPDATE books SET available=available+1 WHERE id=?')->execute([$b]);$pdo->commit();notice('Return recorded.');}header('Location: books.php');exit;}}$books=$pdo->query('SELECT * FROM books ORDER BY title')->fetchAll();$members=$admin?$pdo->query("SELECT id,name FROM users WHERE role='student' ORDER BY name")->fetchAll():[];$loans=$admin?$pdo->query("SELECT l.id,l.due_date,b.title,u.name FROM loans l JOIN books b ON b.id=l.book_id JOIN users u ON u.id=l.user_id WHERE l.status='issued' ORDER BY l.due_date")->fetchAll():[];$edit=null;if($admin&&isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM books WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}layout_start($admin?'Books and circulation':'Book catalogue');?><?php if($admin):?><div class="columns"><section class="panel"><h2><?= $edit?'Edit book':'Add a book'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><?php foreach(['title'=>'Title','author'=>'Author','isbn'=>'ISBN','category'=>'Category','quantity'=>'Total copies','description'=>'Description'] as $k=>$label):?><label><?=e($label)?><input name="<?=e($k)?>" <?=in_array($k,['title','author','quantity'])?'required':''?> value="<?=e($edit[$k]??($k==='quantity'?1:''))?>" <?= $k==='quantity'?'type="number" min="0"':''?>></label><?php endforeach;?><button>Save book</button></form></section><section class="panel"><h2>Issue a book</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="issue"><label>Book<select name="book"><?php foreach($books as $b):if($b['available']>0):?><option value="<?=$b['id']?>"><?=e($b['title'])?> (<?=$b['available']?> available)</option><?php endif;endforeach;?></select></label><label>Student<select name="member"><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select></label><label>Due date<input type="date" name="due" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></label><button>Record issue</button></form></section></div><?php endif;?><section class="panel"><h2>Catalogue</h2><div class="grid"><?php foreach($books as $b):?><article class="book"><div class="cover">▤<small><?=e($b['category'])?></small></div><div><h3><?=e($b['title'])?></h3><p>by <?=e($b['author'])?></p><small><?=e($b['available'])?> / <?=e($b['quantity'])?> available</small><?php if($admin):?><p><a href="books.php?edit=<?=$b['id']?>">Edit details</a></p><?php endif;?></div></article><?php endforeach;?></div><?php if(!$books):?><p class="muted">No books have been added yet.</p><?php endif;?></section><?php if($admin):?><section class="panel"><h2>Active loans — record returns</h2><div class="scroll"><table><tr><th>Book</th><th>Student</th><th>Due date</th><th></th></tr><?php foreach($loans as $l):?><tr><td><?=e($l['title'])?></td><td><?=e($l['name'])?></td><td><?=e($l['due_date'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="return"><input type="hidden" name="loan" value="<?=$l['id']?>"><button class="mini">Return</button></form></td></tr><?php endforeach;?></table></div></section><?php endif;?><?php layout_end();?>